/* BD. CivilLab — Official Nikosh Bengali Font Engine
 * Self-contained Embedded WOFF2 (182KB / Zero Network Delay)
 * + Global CDN Edge Fallback (jsDelivr / sonnetdp / hmoazzem)
 * + Local Machine Font Discovery (Nikosh, NikoshBAN, NikoshLight)
 */

@font-face {
  font-family: 'Nikosh';
  font-style: normal;
  font-weight: 100 900;
  font-display: swap;
  src: url('data:font/woff2;charset=utf-8;base64,') format('woff2'),
       url('https://cdn.jsdelivr.net/gh/sonnetdp/nikosh@master/fonts/Nikosh.woff2') format('woff2'),
       url('https://cdn.jsdelivr.net/gh/hmoazzem/bangla-fonts/Nikosh.ttf') format('truetype'),
       url('/fonts/Nikosh.woff2') format('woff2'),
       url('/fonts/Nikosh.ttf') format('truetype'),
       local('Nikosh'),
       local('NikoshBAN'),
       local('NikoshLight');
}

@font-face {
  font-family: 'Nikosh';
  font-style: normal;
  font-weight: normal;
  font-display: swap;
  src: url('data:font/woff2;charset=utf-8;base64,') format('woff2'),
       url('https://cdn.jsdelivr.net/gh/sonnetdp/nikosh@master/fonts/Nikosh.woff2') format('woff2'),
       url('https://cdn.jsdelivr.net/gh/hmoazzem/bangla-fonts/Nikosh.ttf') format('truetype'),
       url('/fonts/Nikosh.woff2') format('woff2'),
       url('/fonts/Nikosh.ttf') format('truetype'),
       local('Nikosh'),
       local('NikoshBAN'),
       local('NikoshLight');
}

