@font-face {
  font-family: 'NikoshBAN';
  font-style: normal;
  font-weight: 100 900;
  font-display: swap;
  src: url('data:font/woff2;charset=utf-8;base64,') format('woff2'),
       url('https://cdn.jsdelivr.net/gh/sonnetdp/nikosh@master/fonts/Nikosh.woff2') format('woff2'),
       local('NikoshBAN'),
       local('Nikosh');
}

/* Universal Bengali Unicode Mapping: any font stack encountering Bengali glyphs uses Nikosh */
@font-face {
  font-family: 'Inter';
  font-style: normal;
  font-weight: 100 900;
  font-display: swap;
  src: url('data:font/woff2;charset=utf-8;base64,') format('woff2'),
       url('https://cdn.jsdelivr.net/gh/sonnetdp/nikosh@master/fonts/Nikosh.woff2') format('woff2'),
       local('Nikosh'),
       local('NikoshBAN');
  unicode-range: U+0980-09FF;
}

@font-face {
  font-family: 'Georgia';
  font-style: normal;
  font-weight: 100 900;
  font-display: swap;
  src: url('data:font/woff2;charset=utf-8;base64,') format('woff2'),
       url('https://cdn.jsdelivr.net/gh/sonnetdp/nikosh@master/fonts/Nikosh.woff2') format('woff2'),
       local('Nikosh'),
       local('NikoshBAN');
  unicode-range: U+0980-09FF;
}

/* Global Class & Language Selectors for Nikosh */
[lang="bn"],
:lang(bn),
.font-bangla,
.font-bengali,
.font-nikosh,
.nikosh-text,
.nikosh-font {
  font-family: 'Nikosh', 'NikoshBAN', sans-serif !important;
}

/* ==========================================================================
   FORCE NIKOSH FONT ON ALL D3, RECHARTS & SVG CHART COMPONENTS & LABELS
   Maintains visual consistency with the application's Bengali typography
   ========================================================================== */
.recharts-wrapper,
.recharts-wrapper *,
