.recharts-cartesian-axis tspan,
.recharts-cartesian-axis-tick,
.recharts-cartesian-axis-tick text,
.recharts-cartesian-axis-tick-value,
.recharts-polar-angle-axis-tick-value,
.recharts-polar-radius-axis-tick-value,
.recharts-legend-item-text,
.recharts-default-tooltip,
.recharts-tooltip-label,
.recharts-tooltip-item,
.recharts-tooltip-item-name,
.recharts-tooltip-item-value,
.recharts-pie-label-text,
.recharts-radial-bar-label-text,
.recharts-brush text,
.recharts-responsive-container text,
g.recharts-cartesian-axis text,
g.recharts-xAxis text,
g.recharts-yAxis text,
.d3-chart,
.d3-chart text,
.d3-chart tspan,
.d3-axis,
.d3-axis text,
.d3-axis tspan,
.d3-tooltip,
.d3-label,
